create table if not exists public.recording_event_cameras(event_id uuid not null references public.pelada_eventos_partida(id) on delete cascade,session_id uuid not null references public.recording_sessions(id) on delete cascade,recording_offset_ms bigint not null check(recording_offset_ms>=0),created_at timestamptz not null default now(),primary key(event_id,session_id)); create index if not exists recording_event_cameras_session_idx on public.recording_event_cameras(session_id,recording_offset_ms); alter table public.recording_event_cameras enable row level security; grant select on public.recording_event_cameras to authenticated; create policy recording_event_cameras_superadmin_read on public.recording_event_cameras for select to authenticated using(public.is_superadmin()); insert into public.recording_event_cameras(event_id,session_id,recording_offset_ms) select e.id,e.recording_session_id,greatest(0,coalesce(e.recording_offset_ms,extract(epoch from(e.corrected_created_at-s.started_at))*1000)::bigint) from public.pelada_eventos_partida e join public.recording_sessions s on s.id=e.recording_session_id where e.recording_session_id is not null on conflict do nothing; create or replace function public.registrar_evento_em_cameras() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.recording_event_cameras(event_id,session_id,recording_offset_ms) select new.id,s.id,greatest(0,extract(epoch from(new.corrected_created_at-s.started_at))*1000)::bigint from public.recording_sessions s where s.pelada_id=new.pelada_id and s.status='RECORDING' on conflict do nothing; return new; end $$; drop trigger if exists registrar_evento_em_cameras on public.pelada_eventos_partida; create trigger registrar_evento_em_cameras after insert on public.pelada_eventos_partida for each row execute function public.registrar_evento_em_cameras(); alter table public.recording_cuts drop constraint if exists recording_cuts_event_id_key; create unique index if not exists recording_cuts_session_event_unique on public.recording_cuts(session_id,event_id); create or replace function public.superadmin_solicitar_corte_gravacao(p_event_id uuid,p_session_id uuid) returns public.recording_cuts language plpgsql security definer set search_path='' as $$ declare v_event public.pelada_eventos_partida;v_cut public.recording_cuts;v_session_id uuid;v_offset bigint;v_after bigint; begin select * into v_event from public.pelada_eventos_partida where id=p_event_id; if not public.is_superadmin() or v_event.status<>'ACTIVE' or v_event.type not in('GOAL','HIGHLIGHT') then raise exception 'Evento indisponível para corte'; end if; v_session_id=coalesce(p_session_id,v_event.recording_session_id); if v_session_id is null then select session_id into v_session_id from public.recording_event_cameras where event_id=p_event_id order by created_at limit 1; end if; select recording_offset_ms into v_offset from public.recording_event_cameras where event_id=p_event_id and session_id=v_session_id; if v_offset is null then raise exception 'Esta câmera não registrou o evento'; end if; v_after=case when v_event.type='GOAL' then 8000 else 5000 end; insert into public.recording_cuts(session_id,event_id,clip_start_ms,clip_end_ms,status) values(v_session_id,p_event_id,greatest(0,v_offset-10000),v_offset+v_after,'PENDING') on conflict(session_id,event_id) do update set clip_start_ms=excluded.clip_start_ms,clip_end_ms=excluded.clip_end_ms,status='PENDING',error_message=null,updated_at=now() returning * into v_cut; return v_cut; end $$; create or replace function public.superadmin_solicitar_corte_gravacao(p_event_id uuid) returns public.recording_cuts language plpgsql security definer set search_path='' as $$ declare v_session_id uuid; begin select session_id into v_session_id from public.recording_event_cameras where event_id=p_event_id order by created_at limit 1; return public.superadmin_solicitar_corte_gravacao(p_event_id,v_session_id); end $$; revoke all on function public.superadmin_solicitar_corte_gravacao(uuid),public.superadmin_solicitar_corte_gravacao(uuid,uuid) from public; grant execute on function public.superadmin_solicitar_corte_gravacao(uuid),public.superadmin_solicitar_corte_gravacao(uuid,uuid) to authenticated;
